class PersonRequest:
    MAX_NAME_LENGTH = 33
    VALID_SEXES = ("Man", "Woman", "UGM")
    PHONE_NUMBER_LENGTH = 11

    def __init__(self, name: str, sex: str, phoneNumber: str):
        self._name = self._validate_name(name)
        self._sex = self._validate_sex(sex)
        self._phoneNumber = self._validate_phoneNumber(phoneNumber)

    @property
    def name(self) -> str:
        return self._name

    @name.setter
    def name(self, value: str):
        self._name = self._validate_name(value)

    @property
    def sex(self) -> str:
        return self._sex

    @sex.setter
    def sex(self, value: str):
        self._sex = self._validate_sex(value)

    @property
    def phoneNumber(self) -> str:
        return self._phoneNumber

    @phoneNumber.setter
    def phoneNumber(self, value: str):
        self._phoneNumber = self._validate_phoneNumber(value)

    def _validate_name(self, name: str) -> str:
        if not name:
            return None
        if len(name) > self.MAX_NAME_LENGTH:
            return None
        return name

    def _validate_sex(self, sex: str) -> str:
        if sex not in self.VALID_SEXES:
            return None
        return sex

    def _validate_phoneNumber(self, phoneNumber: str) -> str:
        if not phoneNumber:
            return None
        if len(phoneNumber) != self.PHONE_NUMBER_LENGTH or not phoneNumber.isdigit():
            return None
        return phoneNumber
